export const FATHER_QUESTION_REGISTRY: Record<QuizDifficulty, { foundation: QuizQuestion[]; growth: QuizQuestion[]; mastery: QuizQuestion[]; }> = {
  easy: {
    foundation: FATHER_EASY_FOUNDATION,
    growth: FATHER_EASY_GROWTH,
    mastery: FATHER_EASY_MASTERY
  },
  medium: {
    foundation: FATHER_MEDIUM_FOUNDATION,
    growth: FATHER_MEDIUM_GROWTH,
    mastery: FATHER_MEDIUM_MASTERY
  },
  hard: {
    foundation: FATHER_HARD_FOUNDATION,
    growth: FATHER_HARD_GROWTH,
    mastery: FATHER_HARD_MASTERY
  },
};

export function getFatherStageQuestions(difficulty: QuizDifficulty, stage: 1 | 2 | 3): QuizQuestion[] {
  const diffKey = (difficulty || 'easy').toLowerCase() as QuizDifficulty;
  const stageMap = FATHER_QUESTION_REGISTRY[diffKey] || FATHER_QUESTION_REGISTRY.easy;
  if (stage === 1) return stageMap.foundation;
  if (stage === 2) return stageMap.growth;
  return stageMap.mastery;
}

export function getFatherLevelQuestions(difficulty: QuizDifficulty, level: number): QuizQuestion[] {
  const stage = level <= 10 ? 1 : level <= 20 ? 2 : 3;
  const stagePool = getFatherStageQuestions(difficulty, stage);
  const offset = (level - 1) % 10;
  const startIndex = offset * 5;
  return stagePool.slice(startIndex, startIndex + 5);
}
